-- AgentHub AI 能力域结构脚本：40 张 ai_ 表（设计稿 §5 表清单、§6 冻结契约）。
-- 幂等：CREATE TABLE / CREATE INDEX 均带 IF NOT EXISTS，可重复执行；破坏性增列段已折叠进表体，不再单列。
-- 表名与列名属契约面，改动必须同步另一方言、契约常量与受影响模块。

SET NAMES utf8mb4;

create table if not exists ai_model_config ( id bigint(20) not null, config_name varchar(100) not null comment '配置名称', provider varchar(50) not null comment '提供商（openai/dashscope/deepseek/glm/ollama/custom）', model_type varchar(20) not null comment '模型类型（chat 对话 / embedding 向量 / decision 决策 / rerank 重排）', model_code varchar(100) not null comment '模型标识（如 qwen-plus、text-embedding-v3）', supports_vision char(1) default '1' comment '是否支持视觉（图片输入；仅对话模型有意义）：1是 0否', base_url varchar(255) not null comment '服务地址（OpenAI 兼容根地址）', api_key longtext comment 'API 密钥（AES 密文）', dimension int comment '向量维度（embedding 模型必填）', timeout_seconds int default 60 comment '超时时间（秒）', max_retries int default 1 comment '失败重试次数', status char(1) default '0' comment '状态（0正常 1停用）', remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, del_flag char(1) default '0', input_price decimal(12, 6) comment '输入单价（元 / 千 Token），为空按 0 计', output_price decimal(12, 6) comment '输出单价（元 / 千 Token），为空按 0 计', constraint pk_ai_model_config primary key (id), unique key uk_ai_model_config_name (config_name, (if(del_flag = '0', 0, null))) ) engine=innodb default charset=utf8mb4 comment='AI 模型配置表';

create table if not exists ai_knowledge_base ( id bigint(20) not null, kb_name varchar(100) not null, kb_code varchar(100) not null comment '知识库编码（唯一，用于命名 Milvus 集合）', description varchar(500), embedding_model_id bigint(20) not null comment '向量模型（ai_model_config.id，model_type=embedding）', collection_name varchar(100) not null comment 'Milvus 集合名称', dimension int not null comment '向量维度（与向量模型一致）', chunk_size int default 500 comment '切片长度（字符）', chunk_overlap int default 50 comment '切片重叠长度（字符）', retrieval_top_k int default 5 comment '默认召回条数', rerank_enabled char(1) not null default '0' comment '是否启用检索重排（0否 1是）', rerank_model_id bigint(20) comment '重排模型（ai_model_config.id，model_type=rerank）', retrieval_mode varchar(16) not null default 'vector' comment '检索方式（vector 向量 / hybrid 向量+BM25）', bm25_index_status varchar(16) not null default 'none' comment 'BM25 索引状态（none/building/ready/failed）', similarity_threshold decimal(4, 3) default 0.500 comment '默认相似度阈值', status char(1) default '0' comment '状态（0正常 1停用）', remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, del_flag char(1) default '0', owner_dept_id bigint(20) comment '归属部门（visible_scope=1 时生效）', visible_scope varchar(1) default '0' comment '生效范围：0 公开 1 本部门 2 仅本人', constraint pk_ai_knowledge_base primary key (id), unique key uk_ai_knowledge_base_code (kb_code, (if(del_flag = '0', 0, null))) ) engine=innodb default charset=utf8mb4 comment='AI 知识库表';

create table if not exists ai_document ( id bigint(20) not null, kb_id bigint(20) not null, doc_name varchar(255) not null comment '文档名称', file_suffix varchar(20) comment '文件后缀（小写，不含点）', oss_id bigint(20) comment 'OSS 文件 ID（sys_oss.oss_id）', file_url varchar(500) comment '文件访问地址', file_size bigint(20) comment '文件大小（字节）', char_count int default 0 comment '解析后字符数', chunk_count int default 0 comment '切片数量', parse_status char(1) default '0' comment '解析状态（0待解析 1解析中 2已解析 3解析失败）', error_msg varchar(1000) comment '解析失败原因', remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, del_flag char(1) default '0', content longtext comment '解析后的纯文本内容（用于在线预览）', vector_status char(1) default '0' comment '向量化状态（0待向量化 1向量化中 2已向量化 3向量化失败）', vector_error_msg varchar(1000) comment '向量化失败原因', constraint pk_ai_document primary key (id), key idx_ai_document_kb (kb_id) ) engine=innodb default charset=utf8mb4 comment='AI 知识库文档表';

create table if not exists ai_chunk ( id bigint(20) not null, kb_id bigint(20) not null, doc_id bigint(20) not null, chunk_index int not null comment '切片序号（从 0 开始）', content longtext comment '切片正文', char_count int default 0, vector_id varchar(100) comment 'Milvus 中的向量主键', heading_path varchar(500) comment '章节路径（各级标题用 > 连接，如 第2章 > 2.3 考勤）', page_no int comment '切片起始页码（PDF 等分页文档）', char_start int comment '切片在文档纯文本中的起始字符下标（含）', char_end int comment '切片在文档纯文本中的结束字符下标（不含）', create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, constraint pk_ai_chunk primary key (id), key idx_ai_chunk_doc (doc_id), key idx_ai_chunk_kb (kb_id) ) engine=innodb default charset=utf8mb4 comment='AI 知识库文档切片表';

create table if not exists ai_entry_agent ( id bigint(20) not null, agent_name varchar(100) not null, agent_code varchar(100) not null comment '智能体编码（唯一，作为 AgentScope 的 agent name）', description varchar(500), sys_prompt longtext, model_id bigint(20) not null, memory_model_id bigint(20), summary_model_id bigint(20), subagent_model_id bigint(20), daily_token_quota bigint(20) default 0, daily_request_quota int default 0, monthly_token_quota bigint(20) default 0, owner_dept_id bigint(20), visible_scope char(1) default '0', max_iters int default 10, status char(1) default '0', remark varchar(500), singleton char(1) not null default '1' comment '单例行标记（恒 1，配合唯一索引强制「入口智能体全平台唯一」）', create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, del_flag char(1) default '0', constraint pk_ai_entry_agent primary key (id), constraint ck_ai_entry_agent_singleton check (singleton = '1'), unique key uk_ai_entry_agent_code (agent_code, (if(del_flag = '0', 0, null))), unique key uk_ai_entry_agent_singleton (singleton) ) engine=innodb default charset=utf8mb4 comment='AI 入口智能体表（全平台唯一，恒 1 行；REQ-AI-33 起由 ai_agent 拆出）';

create table if not exists ai_expert_agent ( id bigint(20) not null, agent_name varchar(100) not null, agent_code varchar(100) not null comment '智能体编码（唯一，作为 AgentScope 的 agent name 与路由专家 key）', description varchar(500), sys_prompt longtext, model_id bigint(20) not null, memory_model_id bigint(20), summary_model_id bigint(20), subagent_model_id bigint(20), daily_token_quota bigint(20) default 0, daily_request_quota int default 0, monthly_token_quota bigint(20) default 0, owner_dept_id bigint(20), visible_scope char(1) default '0' comment '可见范围（0全员 1本部门 2仅创建人）', max_iters int default 10, status char(1) default '0', remark varchar(500), expert_domain varchar(64) comment '专家领域标签（2026-10-02 起定义页已移除该输入项、不再参与换专家；仅存列）', capability_desc varchar(500) comment '能力描述（注入入口智能体的路由提示词；为空回落 description）', output_contract longtext comment '默认输出契约（JSON Schema 文本，可空）；任务级契约优先', expert_write_enabled char(1) not null default '1' comment '专家写工具开关（恒为 1：允许，按「允许」档生效、「需确认」档走 HITL 确认卡片）', auto_route char(1) not null default '1' comment '是否自动路由（1 进入口智能体的自动候选清单；0 只能被用户手动指定）', memory_enabled char(1) not null default '1' comment '是否启用长期记忆（1 开启 / 0 关闭：不注入也不沉淀长期记忆）', create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, del_flag char(1) default '0', constraint pk_ai_expert_agent primary key (id), constraint ck_ai_expert_agent_auto_route check (auto_route in ('0', '1')), key idx_ai_expert_agent_auto_route (auto_route, status, (if(del_flag = '0', 0, null))), unique key uk_ai_expert_agent_code (agent_code, (if(del_flag = '0', 0, null))) ) engine=innodb default charset=utf8mb4 comment='AI 专家智能体表（可被入口智能体路由；REQ-AI-33 起由 ai_agent 拆出）';

create table if not exists ai_agent_tool ( id bigint(20) not null, agent_id bigint(20) not null, tool_code varchar(100) not null comment '工具编码（由 AiToolCatalog 定义，P2 改为工具注册表驱动）', remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, decision char(1) default '0' comment '工具授权决策（0允许 1需人工确认 2禁止）', constraint pk_ai_agent_tool primary key (id), unique key uk_ai_agent_tool (agent_id, tool_code) ) engine=innodb default charset=utf8mb4 comment='AI 智能体与业务工具关联表';

create table if not exists ai_agent_tool_trust ( id bigint(20) not null, agent_id bigint(20) not null, tool_code varchar(100) not null, user_id bigint(20) not null comment '记住该工具的用户（信任只对该用户生效）', decision varchar(1) not null, source varchar(16) not null, remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, constraint pk_ai_agent_tool_trust primary key (id), unique key uk_ai_agent_tool_trust (agent_id, tool_code, user_id) ) engine=innodb default charset=utf8mb4 comment='AI 智能体 × 工具 × 用户的信任决策表（「记住该工具」沉淀，撤销即删除）';

create table if not exists ai_agent_kb ( id bigint(20) not null, agent_id bigint(20) not null, kb_id bigint(20) not null comment '知识库主键（ai_knowledge_base.id）', remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, constraint pk_ai_agent_kb primary key (id), unique key uk_ai_agent_kb (agent_id, kb_id) ) engine=innodb default charset=utf8mb4 comment='AI 智能体与知识库关联表';

create table if not exists ai_session ( id bigint(20) not null, session_title varchar(200) comment '会话标题（首条用户消息截取生成）', agent_id bigint(20) not null comment '所属智能体（ai_agent.id）', agent_code varchar(100) not null comment '智能体编码快照，智能体删除后仍可追溯', user_id bigint(20) not null comment '归属用户 ID', dept_id bigint(20) comment '归属部门 ID', message_count int default 0 comment '消息条数', status char(1) default '0' comment '状态（0进行中 1已结束）', last_active_time datetime comment '最后活跃时间', remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, del_flag char(1) default '0', top_flag char(1) default '0' comment '置顶标志（0普通 1置顶；置顶会话在列表中优先排序）', source varchar(20) default 'chat' comment '会话来源：chat 手动对话 / task 定时任务 / channel 渠道接入', scenario_pack_id bigint(20) comment '所选场景包（ai_scenario_pack.id，可空；为空时该会话不接入任何 MCP 工具，也不叠加包内工具与技能）', scenario_pack_code varchar(64) comment '场景包编码快照（与 agent_code 同款，避免展示时回查）', pinned_expert_id bigint(20) comment '指定专家（ai_agent.id，可空）：非空＝本会话本轮强制路由到该专家（用户指定，action=pinned），空＝走入口智能体正常决策；会话内可变更（取消指定即置空）', constraint pk_ai_session primary key (id), key idx_ai_session_user (user_id, last_active_time DESC) ) engine=innodb default charset=utf8mb4 comment='AI 会话表（id 即 AgentScope 的 sessionId）';

create table if not exists ai_session_resource ( id bigint(20) not null, session_id bigint(20) not null comment '会话主键（ai_session.id）', resource_type varchar(20) not null comment '资源类型（scenario 场景包 / tool 业务工具 / skill 技能 / mcp_tool MCP 工具）', resource_id bigint(20) not null comment '资源主键（场景包→ai_scenario_pack.id；工具→ai_tool.id；技能→ai_skill.id；MCP 工具→ai_mcp_client.id）', resource_key varchar(200) not null default '' comment '稳定键（展示与去重）：场景包编码 / 工具编码 / 技能名 / MCP 远端工具名', remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, del_flag char(1) default '0' comment '删除标志（0存在 1删除）：叉号移除即逻辑删除，重新选中即新插一行', constraint pk_ai_session_resource primary key (id), key idx_ai_session_resource_session (session_id), unique key uk_ai_session_resource (session_id, resource_type, resource_id, resource_key, (if(del_flag = '0', 0, null))) ) engine=innodb default charset=utf8mb4 comment='AI 会话级资源集（REQ-AI-32）：会话选中的场景包 / 业务工具 / 技能 / MCP 工具，对小Z 与专家同时可见，会话内可增删、下一轮生效';

create table if not exists ai_message ( id bigint(20) not null, session_id bigint(20) not null, role varchar(20) not null comment '角色（user 用户 / assistant 助手 / system 系统）', content longtext comment '消息正文（助手为流式拼接后的完整答案）', reply_id varchar(64) comment 'AgentScope replyId，用于聚合流式块', streaming char(1) default '0' comment '流式状态（0已完成 1流式中）', status char(1) default '0' comment '状态（0正常 1失败）', error_msg varchar(1000) comment '失败原因', tool_call_count int default 0 comment '本轮工具调用次数', prompt_tokens int comment '输入 Token 数', completion_tokens int comment '输出 Token 数', total_tokens int comment '总 Token 数', duration_ms bigint(20) comment '本轮耗时（毫秒）', sources text comment '回答参考来源（JSON 字符串，知识库命中；可空）', remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, del_flag char(1) default '0', constraint pk_ai_message primary key (id), key idx_ai_message_session (session_id, id), key idx_ai_message_create_time (create_time) ) engine=innodb default charset=utf8mb4 comment='AI 会话消息表';

create table if not exists ai_message_attachment ( id bigint(20) not null, session_id bigint(20) not null comment '所属会话（ai_session.id）', message_id bigint(20) comment '所属用户消息（ai_message.id）；为空表示尚未发送的暂存件', file_type varchar(16) not null comment '附件类型（image 图片 / document 文档）', file_name varchar(255) not null comment '原始文件名', file_suffix varchar(32) comment '文件后缀（小写，不含点）', file_size bigint(20) comment '文件大小（字节）', mime_type varchar(64) comment 'MIME 类型（图片为 image/*）', oss_id bigint(20) comment '对象存储主键（sys_oss.oss_id）', parsed_content longtext comment '文档解析后的纯文本（图片为空）', create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, del_flag char(1) default '0', constraint pk_ai_message_attachment primary key (id), key idx_ai_message_attachment_session (session_id), key idx_ai_message_attachment_message (message_id), key idx_ai_message_attachment_pending (message_id, create_time) ) engine=innodb default charset=utf8mb4 comment='AI 会话消息附件表（聊天上传的图片/文档）';

create table if not exists ai_tool_call_log ( id bigint(20) not null, session_id bigint(20) not null comment '所属会话（ai_session.id）', message_id bigint(20) comment '所属助手消息（ai_message.id）', user_id bigint(20) comment '触发用户 ID', tool_call_id varchar(64) comment 'AgentScope toolCallId', tool_name varchar(100) not null comment '工具名称', tool_input longtext comment '入参 JSON（由 tool_call delta 增量拼接）', tool_output longtext comment '结果摘要（截断后）', state varchar(20) comment '结果状态（SUCCESS / ERROR / INTERRUPTED / DENIED）', duration_ms bigint(20) comment '工具执行耗时（毫秒）', remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, agent_id bigint(20) comment '发起该工具调用的智能体主键（入口轮＝会话智能体，专家调用＝专家，无人值守＝对应智能体；历史行为空）', constraint pk_ai_tool_call_log primary key (id), key idx_ai_tool_call_agent (message_id, agent_id), key idx_ai_tool_call_log_session (session_id, id), key idx_ai_tool_call_log_create_time (create_time) ) engine=innodb default charset=utf8mb4 comment='AI 工具调用明细表（物理追加）';

create table if not exists ai_route_run ( id bigint(20) not null, session_id bigint(20) not null comment '用户会话主键（ai_session.id）', message_id bigint(20) comment '本轮的助手消息主键（ai_message.id）', entry_agent_id bigint(20) not null comment '入口智能体主键（本期恒为小Z）', user_id bigint(20) comment '提问用户', action varchar(8) comment '路由决策（self 自答 / route 路由）', decision_json longtext comment '路由决策原文（含 reason / confidence，用于复盘决策质量）', task_context longtext comment '下发给专家的任务片段（原样留档，用于事后核对「到底传了什么」）', expert_call_count int default 0 comment '本次编排的专家调用次数（含重试与换专家）', status varchar(16) default 'running' comment '编排状态：running / success / degraded（降级自答）/ aborted', degrade_reason varchar(500) comment '降级或中止原因', duration_ms bigint(20) comment '编排总耗时（毫秒）', create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, del_flag char(1) default '0', warning_text varchar(1000) comment '编排告警汇总（只告警不阻断）：L3 脱敏命中项（按类型计数）+ 事实篡改抽查不一致项（专家关键数字未在最终回答中出现）；无告警时为空', decision_source char(1) comment '结构化决策判定来源：L 工具决策 / J 决策模型 / K 粘性复用上轮专家（跳过判定）/ F 回落（工具决策兜底）', judge_choice varchar(64) comment '结构化决策：决策模型选择的选项（agent_code / self / other）', judge_confidence decimal(5,4) comment '结构化决策：判定置信度', judge_probabilities text comment '结构化决策：概率分布（JSON 文本，影子校准用）', judge_latency_ms int comment '结构化决策：判定耗时（毫秒）', judge_tokens int comment '结构化决策：判定输入 Token（费用口径）', judge_error varchar(500) comment '结构化决策：判定不可用原因（超时 / 报错 / 越界 / margin_rejected 边际不足 / circuit_breaker_open 熔断中）', judge_mode char(1) comment '结构化决策：本轮执行模式 S 影子 / G 闸门', constraint pk_ai_route_run primary key (id), key idx_ai_route_run_message (message_id), key idx_ai_route_run_session (session_id, id), key idx_ai_route_run_create_time (create_time) ) engine=innodb default charset=utf8mb4 comment='AI 编排运行表（入口智能体的每一轮编排一行；自答时也落一行用于统计路由命中率）';

create table if not exists ai_route_expert_call ( id bigint(20) not null, route_run_id bigint(20) not null comment '所属编排（ai_route_run.id）', expert_agent_id bigint(20) not null comment '被调用的专家智能体主键（ai_agent.id）', expert_session_id varchar(128) comment '专家独立会话标识（routeRunId#expertAgentId），与用户会话完全隔离', attempt_no int default 1 comment '第几次尝试（从 1 起）', call_kind varchar(8) comment '调用类型：first 首次 / retry 同专家重试 / switch 换专家', contract_json longtext comment '本次下发的输出契约（第 3 次尝试记录放宽后的 partial 契约，便于核对当时按哪个松紧度判定）', raw_output longtext comment '专家原始输出原文（不改写、不裁剪，供前端来源卡片与事后追溯）', parsed_output longtext comment '通过契约校验后的结构化结果（JSON 文本）', validation_error varchar(1000) comment '结构校验失败原因（重试时回传给专家）', status varchar(16) comment '调用状态：success / invalid / failed / timeout / pending_confirm / cancelled', prompt_tokens bigint(20) comment '该次调用的输入 Token（计入编排总预算）', completion_tokens bigint(20) comment '该次调用的输出 Token', duration_ms bigint(20) comment '该次调用耗时（毫秒）', create_dept bigint(20), create_by bigint(20), create_time datetime, constraint pk_ai_route_expert_call primary key (id), key idx_ai_route_call_expert (expert_agent_id, create_time DESC), key idx_ai_route_call_run (route_run_id, attempt_no), key idx_ai_route_expert_call_create_time (create_time) ) engine=innodb default charset=utf8mb4 comment='AI 专家调用明细表（一次专家调用一行；追加型，物理删除）';

create table if not exists ai_tool ( id bigint(20) not null, tool_code varchar(100) not null, tool_name varchar(100) not null, description varchar(500), tool_type char(1) default '0' comment '工具类型（0只读 1写入；写入类需 P2 的 HITL 确认闭环）', params_schema longtext comment '参数定义（JSON Schema）', impl_name varchar(100) comment '代码侧实现标识（AiToolFactory 中的 key）', status char(1) default '0' comment '状态（0启用 1停用；停用后不再装配进智能体）', remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, del_flag char(1) default '0', mcp_exposed char(1) default '0' comment '是否对外暴露给 MCP 出口（0否 1是；仅只读工具可勾选）', constraint pk_ai_tool primary key (id), unique key uk_ai_tool_code (tool_code, (if(del_flag = '0', 0, null))) ) engine=innodb default charset=utf8mb4 comment='业务工具注册表（可被智能体调用的语义化工具）';

create table if not exists ai_mcp_client ( id bigint(20) not null, server_name varchar(100) not null comment 'Server 名称（唯一，作为 ToolsConfig.mcpServers 的键）', transport varchar(20) not null comment '传输方式（sse / http；不放开 stdio）', url varchar(500) not null comment 'Server 地址（sse 或 streamable-http 端点）', headers_json longtext comment '请求头 JSON（AES 密文，可承载 Authorization 等凭据，接口不回显明文）', enable_tools varchar(2000) comment '工具白名单（逗号分隔；为空表示放行该 Server 全部工具）', timeout_ms int comment '单次请求超时（毫秒），为空取框架默认', init_timeout_ms int comment '初始化超时（毫秒），为空取框架默认', description varchar(500), status char(1) default '0' comment '状态（0启用 1停用；停用后不再接入智能体装配）', remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, del_flag char(1) default '0', constraint pk_ai_mcp_client primary key (id), unique key uk_ai_mcp_client_name (server_name, (if(del_flag = '0', 0, null))) ) engine=innodb default charset=utf8mb4 comment='外部 MCP Server 连接配置表（平台级，全部智能体可用）';

create table if not exists ai_tool_tag ( id bigint(20) not null, tag_name varchar(50) not null comment '标签名称（唯一，最长 50 字）', remark varchar(500) comment '备注（用途说明，便于管理大量标签）', create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, del_flag char(1) default '0', constraint pk_ai_tool_tag primary key (id), unique key uk_ai_tool_tag_name (tag_name, (if(del_flag = '0', 0, null))) ) engine=innodb default charset=utf8mb4 comment='业务工具标签定义表';

create table if not exists ai_tool_tag_rel ( id bigint(20) not null, tool_id bigint(20) not null comment '业务工具主键（ai_tool.id）', tag_id bigint(20) not null comment '标签主键（ai_tool_tag.id）', create_time datetime, constraint pk_ai_tool_tag_rel primary key (id), key idx_ai_tool_tag_rel_tag (tag_id), unique key uk_ai_tool_tag_rel (tool_id, tag_id) ) engine=innodb default charset=utf8mb4 comment='业务工具与标签关联表（物理删除）';

create table if not exists ai_skill ( id bigint(20) not null, name varchar(255) not null comment '技能标识（唯一，即 AgentScope 的 skillId）', description longtext not null comment '技能用途说明（供模型判断是否加载）', skill_content longtext not null comment 'SKILL.md 全文（YAML frontmatter + Markdown 正文）', source varchar(255) not null default 'agenthub' comment '技能来源（本项目维护的固定为 agenthub）', metadata_json longtext comment '技能元数据 JSON（框架读取用，可为空）', created_at datetime, updated_at datetime, owner_dept_id bigint(20) comment '归属部门（visible_scope=1 时生效）', visible_scope varchar(1) default '0' comment '生效范围：0 公开 1 本部门 2 仅本人', status char(1) default '0' comment '状态（0启用 1停用）', remark varchar(500), create_dept bigint(20), create_by bigint(20), update_by bigint(20), constraint pk_ai_skill primary key (id), unique key uk_ai_skill_name (name) ) engine=innodb default charset=utf8mb4 comment='AI 技能表（正文即 SKILL.md；列结构兼容 AgentScope 技能仓库）';

create table if not exists ai_skill_resource ( id bigint(20) not null, resource_path varchar(500) not null comment '相对路径（如 references/faq.md）', resource_content longtext not null comment '文件内容', created_at datetime, updated_at datetime, constraint pk_ai_skill_resource primary key (id, resource_path), constraint fk_ai_skill_resource_skill FOREIGN KEY (id) REFERENCES ai_skill(id) ON DELETE CASCADE ) engine=innodb default charset=utf8mb4 comment='AI 技能参考资料表（id 即所属技能主键）';

create table if not exists ai_agent_skill ( id bigint(20) not null, agent_id bigint(20) not null, skill_id bigint(20) not null comment '技能主键（ai_skill.id）', remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, constraint pk_ai_agent_skill primary key (id), unique key uk_ai_agent_skill (agent_id, skill_id) ) engine=innodb default charset=utf8mb4 comment='AI 智能体与技能关联表';

create table if not exists ai_subagent ( id bigint(20) not null, name varchar(100) not null comment '子智能体标识（唯一，即 AgentScope SubagentDeclaration 的 name / agent_id）', description varchar(1000) not null comment '用途说明（主智能体据此决定是否委派，务必写清何时使用）', sys_prompt longtext comment '子智能体系统提示词（即 inlineAgentsBody；为空时使用框架通用子智能体提示词）', workspace_mode varchar(16) default 'ISOLATED' comment '工作区模式：ISOLATED 隔离工作区 / SHARED 与主智能体共享工作区', model_id bigint(20) comment '指定模型（ai_model_config.id，可空；为空时用 ai_agent.subagent_model_id，再为空则继承主模型）', steps int default 10 comment '单次最大推理迭代次数（框架默认 10）', tool_codes longtext comment '工具白名单（JSON 数组，仅允许 ai_tool.tool_type=0 的只读工具）', status char(1) default '0' comment '状态（0启用 1停用）', remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, constraint pk_ai_subagent primary key (id), unique key uk_ai_subagent_name (name) ) engine=innodb default charset=utf8mb4 comment='AI 子智能体定义表（平台级可复用，与智能体多对多绑定）';

create table if not exists ai_agent_subagent ( id bigint(20) not null, agent_id bigint(20) not null, subagent_id bigint(20) not null comment '子智能体主键（ai_subagent.id）', remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, constraint pk_ai_agent_subagent primary key (id), unique key uk_ai_agent_subagent (agent_id, subagent_id) ) engine=innodb default charset=utf8mb4 comment='AI 智能体与子智能体关联表';

create table if not exists ai_channel ( id bigint(20) not null, channel_name varchar(100) not null comment '渠道名称', channel_code varchar(64) not null comment '渠道编码（唯一，回调地址中的路径标识）', platform_type varchar(20) not null comment '平台类型：feishu 飞书 / wecom 企业微信 / github GitHub / dingtalk 钉钉（长连接）', mode varchar(16) not null default 'webhook' comment '接入形态：webhook Webhook 回调（默认，需平台公网可达） / ws 长连接（应用主动外连、免公网 IP；仅飞书区分）', agent_id bigint(20) not null comment '默认智能体（ai_agent.id）', app_id varchar(200) comment '应用标识（飞书 appId / 企微 corpId / 钉钉 AppKey；GitHub 为空）', app_secret varchar(500) comment '应用密钥（AES 密文；飞书 appSecret / 企微 secret / 钉钉 AppSecret）', platform_agent_id varchar(64) comment '平台内应用 ID（企微 agentId / 钉钉 RobotCode；其它平台为空）', encrypt_key varchar(500) comment '回调加解密密钥（AES 密文；飞书 Encrypt Key / 企微 EncodingAESKey）', verification_token varchar(500) comment '回调校验口令（AES 密文；飞书 Verification Token / 企微 Token）', webhook_secret varchar(500) comment 'Webhook 签名密钥（AES 密文；GitHub Webhook Secret）', api_token varchar(500) comment '平台访问令牌（AES 密文；GitHub PAT）', api_base varchar(200) comment '平台 API 基地址（飞书 / 企微 / GitHub / 钉钉 OpenAPI；留空用各平台默认值）', status char(1) default '0' comment '状态（0启用 1停用）', remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, del_flag char(1) default '0', constraint pk_ai_channel primary key (id), unique key uk_ai_channel_code (channel_code, (if(del_flag = '0', 0, null))) ) engine=innodb default charset=utf8mb4 comment='AI 渠道接入配置（REQ-AI-24）';

create table if not exists ai_channel_identity ( id bigint(20) not null, channel_id bigint(20) not null comment '所属渠道（ai_channel.id）', external_user_id varchar(200) not null comment '外部用户标识（飞书 open_id / 企微 UserID / GitHub login）', platform_user_id bigint(20) not null comment '映射到的平台用户（sys_user.user_id）', status char(1) default '0' comment '状态（0启用 1停用）', remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, del_flag char(1) default '0', constraint pk_ai_channel_identity primary key (id), unique key uk_ai_channel_identity (channel_id, external_user_id, (if(del_flag = '0', 0, null))) ) engine=innodb default charset=utf8mb4 comment='AI 渠道外部身份映射（REQ-AI-24）';

create table if not exists ai_channel_thread ( id bigint(20) not null, channel_id bigint(20) not null comment '所属渠道（ai_channel.id）', thread_key varchar(300) not null comment '线程标识（框架 Peer.key() 口径：<peerKind>:<peerId>，kind 为小写 direct / group / thread，如 direct:oc_xxx、thread:owner/repo#7）', session_id bigint(20) not null comment '映射到的会话（ai_session.id）', create_time datetime, last_active_time datetime, constraint pk_ai_channel_thread primary key (id), unique key uk_ai_channel_thread (channel_id, thread_key) ) engine=innodb default charset=utf8mb4 comment='AI 渠道消息线程与会话映射（REQ-AI-24）';

create table if not exists ai_agent_task ( id bigint(20) not null, task_name varchar(100) not null comment '任务名称', agent_id bigint(20) not null comment '运行的智能体（ai_agent.id）', agent_code varchar(100) not null comment '智能体编码快照，智能体删除后仍可追溯', task_prompt longtext not null comment '任务提示词（作为每轮对话的用户消息）', cron_expression varchar(100) not null comment 'Cron 表达式（Spring 6 位：秒 分 时 日 月 周）', run_as_user_id bigint(20) not null comment '运行身份用户（会话与数据权限按该用户）', run_as_dept_id bigint(20) comment '运行身份部门（随运行身份用户带出）', last_run_time datetime comment '上次计划执行时间（到点判定与抢占去重基准）', status char(1) default '0' comment '状态（0启用 1停用）', remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, del_flag char(1) default '0', constraint pk_ai_agent_task primary key (id), unique key uk_ai_agent_task_name (task_name, (if(del_flag = '0', 0, null))) ) engine=innodb default charset=utf8mb4 comment='AI 定时任务表';

create table if not exists ai_agent_task_run ( id bigint(20) not null, task_id bigint(20) not null comment '所属任务（ai_agent_task.id）', task_name varchar(100) comment '任务名称快照', agent_id bigint(20) comment '智能体主键快照', session_id bigint(20) comment '本次执行产生的会话（ai_session.id）', message_id bigint(20) comment '本次执行的助手消息（ai_message.id）', trigger_type char(1) default '0' comment '触发方式（0定时 1手动）', status char(1) default '2' comment '状态（0成功 1失败 2执行中）', start_time datetime comment '开始时间', end_time datetime comment '结束时间', duration_ms bigint(20) comment '执行耗时（毫秒）', prompt_tokens int, completion_tokens int, total_tokens int comment '总 Token 数', tool_call_count int default 0 comment '工具调用次数', error_msg varchar(1000) comment '失败原因', remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, constraint pk_ai_agent_task_run primary key (id), key idx_ai_agent_task_run_session (session_id), key idx_ai_agent_task_run_task (task_id, id DESC), key idx_ai_agent_task_run_create_time (create_time) ) engine=innodb default charset=utf8mb4 comment='AI 定时任务执行记录表（物理追加）';

create table if not exists ai_usage_stat ( id bigint(20) not null, stat_date date not null comment '统计日期', agent_id bigint(20) not null comment '智能体主键；知识库入库等无智能体归属的平台调用固定为 0', model_id bigint(20), user_id bigint(20) not null, usage_type char(1) not null default '0' comment '用量类型（0对话 1知识库入库）', prompt_tokens bigint(20) default 0, completion_tokens bigint(20) default 0, total_tokens bigint(20) default 0, request_count int default 0 comment '请求（对话轮次）数；知识库入库固定为 0', tool_call_count int default 0 comment '工具调用次数', cost decimal(14, 6) default 0 comment '费用估算（元；按模型单价计算，未配置单价按 0 计）', create_time datetime, update_time datetime, constraint pk_ai_usage_stat primary key (id), key idx_ai_usage_user (user_id, stat_date DESC), unique key uk_ai_usage (stat_date, agent_id, model_id, user_id, usage_type) ) engine=innodb default charset=utf8mb4 comment='AI 用量统计表（按日期 / 智能体 / 模型 / 用户 / 用量类型聚合）';

create table if not exists ai_daily_digest ( id bigint(20) not null, digest_date date not null comment '日报日期（唯一；重跑按日期 upsert）', level char(1) default '0' comment '结论级别（0平稳 1需关注 2需处理）', digest_text longtext comment '日报正文（人话版；落库保真，便于回看与推送失败补投）', usage_total_tokens bigint(20) default 0 comment '当日总 Token', usage_request_count int default 0 comment '当日请求（对话轮次）数', usage_tool_call_count int default 0 comment '当日工具调用次数', usage_compare_pct decimal(6, 2) comment 'Token 环比（%；无上日数据时为 NULL）', quota_usage_pct decimal(6, 2) comment '配额使用率（%；配额为 0 即不限时为 NULL）', task_run_count int default 0 comment '定时任务执行次数', task_fail_count int default 0 comment '定时任务失败次数', backlog_count int default 0 comment '工作流待办积压条数（按运行中任务计）', backlog_top_node varchar(100) comment '积压最多的节点名', backlog_max_wait_minutes int comment '最久滞留分钟数', perm_allow_count int default 0 comment '权限决策-允许次数', perm_ask_count int default 0 comment '权限决策-需确认次数', perm_deny_count int default 0 comment '权限决策-拒绝次数', login_success_count int default 0 comment '登录成功次数', login_fail_count int default 0 comment '登录失败次数', login_anomaly_count int default 0 comment '登录异动次数（异地或新 IP）', task_run_id bigint(20) comment '来源任务执行记录（ai_agent_task_run.id）', session_id bigint(20) comment '来源会话（ai_session.id）', remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, constraint pk_ai_daily_digest primary key (id), unique key uk_ai_daily_digest_date (digest_date) ) engine=innodb default charset=utf8mb4 comment='AI 平台运行日报表（每天一条；由任务产出投递器写入）';

create table if not exists ai_permission_decision_log ( id bigint(20) not null, session_id bigint(20), message_id bigint(20), agent_id bigint(20), user_id bigint(20), tool_code varchar(100), tool_name varchar(100), decision char(1) comment '决策（0允许 1需确认 2禁止）', decision_source varchar(32) comment '决策来源（agent_tool 显式策略 / remember 记住规则 / global_mode 全局模式 / fallback 兜底）', matched_rule varchar(64), reason varchar(500), tool_input longtext, confirmed char(1) comment '人工确认结果（0拒绝 1确认；非 ASK 决策为空）', confirm_source varchar(16) comment '确认作用范围（once 仅本次 / remember 记住该工具）', duration_ms bigint(20), create_time datetime, constraint pk_ai_permission_decision_log primary key (id), key idx_ai_perm_log_session (session_id, message_id), key idx_ai_perm_log_tool (tool_code, decision), key idx_ai_perm_log_user (user_id, create_time DESC), key idx_ai_perm_log_create_time (create_time) ) engine=innodb default charset=utf8mb4 comment='AI 工具权限决策日志（ALLOW / ASK / DENY 全量留痕）';

create table if not exists ai_trace ( id bigint(20) not null, session_id bigint(20) not null comment '会话主键（ai_session.id）', message_id bigint(20) comment '助手消息主键（暂停阶段为待确认消息，恢复段更新同一条）', agent_id bigint(20) not null comment '智能体主键（ai_agent.id）', source varchar(8) default 'chat' comment '任务来源：chat 实时对话 / task 定时任务 / channel 渠道接入', user_id bigint(20) comment '触发用户（定时任务为运行身份用户）', model_id bigint(20) comment '执行时使用的主对话模型主键（ai_model_config.id）', model_code varchar(200) comment '执行时主对话模型标识（快照，事后改配置不改写历史）', model_provider varchar(64) comment '执行时主对话模型提供商', summary_model_code varchar(200) comment '执行时压缩摘要模型标识（未配置为空）', memory_model_code varchar(200) comment '执行时记忆抽取与合并模型标识（未配置为空）', subagent_model_code varchar(200) comment '执行时子智能体默认模型标识（未配置为空）', context_json longtext comment '上下文清单 JSON（工具白名单 / 知识库 / 技能 / 子智能体 / MCP / 各运行期开关）', transitions_json longtext comment '状态迁移 JSON 数组：[{at, state, detail}]', status varchar(16) default 'running' comment '链路状态：running / pending_confirm / success / failed / aborted', duration_ms bigint(20) comment '总耗时（毫秒，含恢复段则累加）', tool_call_count int comment '工具调用次数', prompt_tokens int, completion_tokens int, total_tokens int, error_msg varchar(1000), create_time datetime, update_time datetime, parent_trace_id bigint(20) comment '父链路（编排链路为父、每次专家调用为子；null 表示顶层）', constraint pk_ai_trace primary key (id), key idx_ai_trace_agent (agent_id, create_time DESC), key idx_ai_trace_message (message_id), key idx_ai_trace_parent (parent_trace_id), key idx_ai_trace_session (session_id), key idx_ai_trace_create_time (create_time) ) engine=innodb default charset=utf8mb4 comment='AI 链路追踪表（一次任务一条：执行期模型版本 + 上下文清单 + 状态迁移）';

create table if not exists ai_scenario_pack ( id bigint(20) not null, pack_code varchar(64) not null comment '场景包编码（唯一，创建后不可修改）', pack_name varchar(100) not null comment '场景包名称（如「财务场景包」「人力场景包」）', description varchar(500) comment '用途说明（创建任务时供用户判断该选哪个包）', visible_scope char(1) not null default '0' comment '生效范围（0 公开 / 1 本部门 / 2 仅本人）', owner_dept_id bigint(20) comment '归属部门（visible_scope=1 时比较该列）', status char(1) not null default '0' comment '状态（0 启用 1 停用）', remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, del_flag char(1) default '0', constraint pk_ai_scenario_pack primary key (id), unique key uk_ai_scenario_pack_code (pack_code, (if(del_flag = '0', 0, null))) ) engine=innodb default charset=utf8mb4 comment='AI 场景包定义表（按角色 / 部门打包业务工具 + MCP 工具 + 技能，对话时选用以增强能力）';

create table if not exists ai_scenario_pack_tool ( id bigint(20) not null, pack_id bigint(20) not null, tool_code varchar(64) not null comment '业务工具编码（ai_tool.tool_code）', decision char(1) not null default '1' comment '授权决策（0 允许 / 1 需确认 / 2 禁止），同一工具以包内决策优先', remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, constraint pk_ai_scenario_pack_tool primary key (id), unique key uk_ai_scenario_pack_tool (pack_id, tool_code) ) engine=innodb default charset=utf8mb4 comment='场景包 × 业务工具（含授权决策，叠加到智能体既有绑定之上）';

create table if not exists ai_scenario_pack_mcp_tool ( id bigint(20) not null, pack_id bigint(20) not null, mcp_client_id bigint(20) not null comment 'MCP 连接主键（ai_mcp_client.id）', tool_name varchar(200) not null comment '远端自声明的工具名（即 ai_mcp_client.enable_tools 的白名单口径；注册进工具箱时会被归一化重命名）', decision char(1) not null default '1' comment '授权决策（0 允许 / 1 需确认 / 2 禁止）', remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, constraint pk_ai_scenario_pack_mcp_tool primary key (id), unique key uk_ai_scenario_pack_mcp_tool (pack_id, mcp_client_id, tool_name) ) engine=innodb default charset=utf8mb4 comment='场景包 × 外部 MCP 工具（仅装配包内勾选项；未选包的会话不接入 MCP）';

create table if not exists ai_scenario_pack_skill ( id bigint(20) not null, pack_id bigint(20) not null, skill_id bigint(20) not null comment '技能主键（ai_skill.id）', remark varchar(500), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, constraint pk_ai_scenario_pack_skill primary key (id), unique key uk_ai_scenario_pack_skill (pack_id, skill_id) ) engine=innodb default charset=utf8mb4 comment='场景包 × 技能（叠加到智能体既有技能绑定之上，仍受技能生效范围过滤）';

create table if not exists ai_sensitive_word ( id bigint(20) not null, word varchar(200) not null comment '敏感词或正则表达式', is_regex char(1) default '0' comment '是否正则：0否（子串匹配） 1是', category varchar(50) comment '分类（可空，供分组管理与统计）', enabled char(1) default '1' comment '是否启用：1启用 0禁用', remark varchar(255), create_dept bigint(20), create_by bigint(20), create_time datetime, update_by bigint(20), update_time datetime, del_flag char(1) default '0', constraint pk_ai_sensitive_word primary key (id), key idx_ai_sensitive_word_enabled (del_flag, enabled) ) engine=innodb default charset=utf8mb4 comment='AI 敏感词库（支持普通词与正则，供输入 / 输出 / 渠道出站安全校验）';

create table if not exists ai_safety_event ( id bigint(20) not null, scene varchar(20) comment '场景（input 用户输入 / output 模型输出 / channel_out 渠道出站）', action varchar(20) comment '处置动作（log 只记录 / mask 脱敏放行 / block 阻断）', engine varchar(20) comment '命中引擎（word 敏感词 / pii 隐私信息）', session_id bigint(20), message_id bigint(20), agent_id bigint(20), user_id bigint(20), hit_count int comment '命中项数量', hits_json text comment '命中项 JSON 数组（命中词 / PII 类型）', text_excerpt varchar(255) comment '触发文本摘要（截断至 200 字符）', create_time datetime, constraint pk_ai_safety_event primary key (id), key idx_ai_safety_event_create_time (create_time), key idx_ai_safety_event_scene (scene) ) engine=innodb default charset=utf8mb4 comment='AI 安全事件留痕（敏感词 / PII 命中与处置，追加型明细）';
